type 'a stat = {
  mutable value:'a;
  printer: Format.formatter -> 'a -> unit;
  name   : string;
}

module Stats = struct

let timing_map = Hashtbl.create 42

let get_timings () = timing_map

let add_timing name time =
  let old_t, old_n =
    try Hashtbl.find timing_map name
    with Not_found -> 0.0, 0 in
  Hashtbl.replace timing_map name (old_t +. time, old_n + 1)

let record_timing name f =
  if test_flag stats then
    let begin_time = Unix.gettimeofday () in
    Fun.protect f
      ~finally:(fun () -> add_timing name (Unix.gettimeofday () -. begin_time))
  else f ()

  let registered_stats :  (Format.formatter -> unit) list ref = ref []

  let print fmt =
    List.iter (fun s -> Format.fprintf fmt "<stats>@[%t@]@." s) !registered_stats;
    Hashtbl.iter (fun s (t, n) ->
        Format.fprintf fmt "<stats>@[%s: %f, %d@]@." s t n)
      timing_map

  let () =
    at_exit (fun () ->
        if test_flag stats then begin
            print !formatter;
            Format.pp_print_flush !formatter ()
          end)

(* top-level code disabled because issue #383 and nobody knows why this code was for

  (** SIGXCPU cpu time limit reached *)
  let _ =
    (* TODO? have a possible callback for printing different message*)
    Sys.signal Sys.sigint (Sys.Signal_handle (fun _ -> exit 2))
*)

  let register ~print ~name ~init =
    let s = {name = name; printer = print; value = init} in
    registered_stats :=
      (fun fmt -> Format.fprintf fmt "%s: %a" s.name s.printer s.value)
      :: !registered_stats;
    s

  let mod0 stat f =
    if test_flag stats then stat.value <- f stat.value
  let mod1 stat f x =
    if test_flag stats then stat.value <- f stat.value x
  let mod2 stat f x y =
    if test_flag stats then stat.value <- f stat.value x y

  let register_int ~name ~init =
    register ~print:Format.pp_print_int ~name ~init

  let incr r = if test_flag stats then r.value <- r.value + 1
  let decr r = if test_flag stats then r.value <- r.value - 1

end

  let () = Exn_printer.register (fun fmt e -> match e with
    | IllegalEscape -> Format.pp_print_string fmt "illegal escape"
    | IllegalCharInString -> Format.pp_print_string fmt "illegal character in string"
    | UnterminatedString -> Format.pp_print_string fmt "unterminated string"
    | _ -> raise e)

  let loc lb = Loc.extract (lb.lex_start_p,lb.lex_curr_p)

  let char_for_backslash = function
    | '\\' -> '\\'
    | 'n'  -> '\n'
    | 'r'  -> '\r'
    | 't'  -> '\t'
    | 'b'  -> '\b'
    | '\'' -> '\''
    | '\"' -> '\"'
    | _ -> raise IllegalCharInString

  let string_to_char s fmt =
    Scanf.sscanf s fmt Char.chr

  let utf8_extra_bytes = function
    | '\000'..'\127' -> 0
    | '\192'..'\223' -> 1
    | '\224'..'\239' -> 2
    | '\240'..'\247' -> 3
    | _ -> -1

  let adjust_pos lexbuf n =
    let pos = lexbuf.lex_curr_p in
    lexbuf.lex_curr_p <- { pos with pos_cnum = pos.pos_cnum - n };
    lexbuf.lex_abs_pos <- lexbuf.lex_abs_pos - n
    (* invariant of Lexing: pos_cnum = lex_abs_pos + lex_curr_pos,
       with lex_curr_pos the offset in the current buffer *)

  let adjust_pos_utf8 lexbuf s =
    let l = String.length s in
    let rec aux i ofs =
      if i >= l then ofs else
      (* FIXME: combining characters should increase n by one more *)
      let n = utf8_extra_bytes s.[i] in
      if n <> -1 then
        aux (i + 1 + n) (ofs + n)
      else
        aux (i + 1) ofs in
    let n = aux 0 0 in
    adjust_pos lexbuf n

}

let dec     = ['0'-'9']
let oct     = ['0'-'7']
let hex     = ['0'-'9' 'a'-'f' 'A'-'F']

let newline = '\r'* '\n'

rule utf8_tail b n = parse
  | eof
      { false }
  | ['\128'-'\191'] as c
      { Buffer.add_char b c;
        n == 1 || utf8_tail b (n - 1) lexbuf }
  | _ { false }

and comment = parse
  | "(*)"
      { comment lexbuf }
  | "*)"
      { () }
  | "(*"
      { comment lexbuf; comment lexbuf }
  | newline
      { new_line lexbuf; comment lexbuf }
  | eof
      { raise Not_found }
  | _ as c
      { let n = utf8_extra_bytes c in
        if n > 0 then adjust_pos lexbuf n;
        comment lexbuf }

and string buf = parse
  | "\""
      { Buffer.contents buf }
  | "\\" newline
      { new_line lexbuf;
        string_skip_spaces buf lexbuf }
  | "\\" (['0'-'1'] dec dec as c) | "\\" ('2' ['0'-'4'] dec as c) | "\\" ('2' '5' ['0'-'5'] as c)
      { Buffer.add_char buf (string_to_char c "%3d");
        string buf lexbuf }
  | "\\x" (hex hex as c)
      { Buffer.add_char buf (string_to_char c "%2x");
        string buf lexbuf }
  | "\\o" (['0'-'3'] oct oct as c)
      { Buffer.add_char buf (string_to_char c "%3o");
        string buf lexbuf }
  | "\\" (_ as c)
      { try Buffer.add_char buf (char_for_backslash c);
            string buf lexbuf
        with IllegalCharInString ->
          raise (Loc.Located (loc lexbuf,IllegalEscape))}
  | eof
      { raise (Loc.Located (loc lexbuf, UnterminatedString)) }
  | ['\032'-'\126'] as c
      { Buffer.add_char buf c;
        string buf lexbuf }
  | _
      { raise (Loc.Located (loc lexbuf, IllegalCharInString)) }

and string_skip_spaces buf = parse
  | [' ' '\t']*
      { string buf lexbuf }

